  if(!buffer||!Number.isFinite(buffer.sampleRate)||!Number.isFinite(buffer.duration)||!buffer.numberOfChannels||typeof buffer.getChannelData!=='function')throw new Error('원본 내레이션 데이터를 읽지 못했어요.');
