  const counts=segments.map(segment=>Math.round((segment.end-segment.start)*sampleRate)),total=counts.reduce((sum,count)=>sum+count,0);if(!Number.isFinite(maxSeconds)||maxSeconds<.25||maxSeconds>180.5||total>maxSeconds*sampleRate)throw new Error(`쇼츠 음성은 최대 ${Math.floor(maxSeconds)}초 범위로 만들어 주세요.`);
